import{_ as c,C as l,o as n,c as s,j as d,a as t,E as o,a5 as r}from"./chunks/framework.CINlqUGR.js";const P=JSON.parse('{"title":"字段集","description":"","frontmatter":{},"headers":[],"relativePath":"components/fieldset.md","filePath":"components/fieldset.md","lastUpdated":1787185306000}'),h={name:"components/fieldset.md"},b={id:"字段集",tabindex:"-1"};function u(f,e,p,g,q,x){const i=l("Badge"),a=l("XhDemo");return n(),s("div",null,[d("h1",b,[e[0]||(e[0]=t("字段集 ",-1)),o(i,{type:"info",text:"fieldset"}),e[1]||(e[1]=t()),e[2]||(e[2]=d("a",{class:"header-anchor",href:"#字段集","aria-label":'Permalink to "字段集 <Badge type="info" text="fieldset" />"'},"​",-1))]),e[3]||(e[3]=r('<p>把若干相关字段收成一组，组标题由 <code>legend</code> 给，禁用与无效沿这一组下发。</p><p>根节点是原生 <code>&lt;fieldset&gt;</code>：整组禁用只写一个属性，浏览器就把组内所有表单控件一并停掉——这是本组件存在的理由，换成 <code>&lt;div&gt;</code> 只剩一层灰样式。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>一份表单里有几段主题相同的字段（收货信息、发票抬头、通知偏好），需要一个组标题把它们收起来。</li><li>需要一次禁用一整段字段，而不是逐个控件写 <code>disabled</code>。</li><li>一组单选或复选选项需要共用一个问句作为组名。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>只有一个控件加一个标签：用<a href="./field">表单字段</a>，字段管一格，字段集管一组格。</li><li>需要整表的值管理与校验：外面套<a href="./form">表单</a>，字段集只管把一段字段圈起来。</li><li>只想在视觉上分段、没有共同的组名与共同的禁用语义：用<a href="./separator">分割线</a>或<a href="./card">卡片</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>disabled</code> 落成原生 <code>fieldset[disabled]</code>，组内控件不可聚焦、不可编辑、不参与提交，无需逐个控件接线。</li><li>说明文字与错误文案自动派生 <code>id</code> 并接进根节点的 <code>aria-describedby</code>，作者不写 <code>id</code>。</li><li>错误文案带 <code>role=&quot;alert&quot;</code>，节点常挂、靠 <code>hidden</code> 显隐，<code>invalid</code> 翻转的那一刻读屏立即播报。</li><li><code>invalid</code> 落成 <code>data-invalid</code>，皮肤据此把组标题转成警示色，同时把错误文案接进描述链并显出。</li><li><code>required</code> 落成 <code>data-required</code>，皮肤据此给组标题加星号。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>一组字段收进原生 fieldset：legend 是这一组的名字，说明文案自动派生 id 并接进 aria-describedby</p>',11)),o(a,{src:"fieldset/01-basic"}),e[4]||(e[4]=d("h3",{id:"整组禁用",tabindex:"-1"},[t("整组禁用 "),d("a",{class:"header-anchor",href:"#整组禁用","aria-label":'Permalink to "整组禁用"'},"​")],-1)),e[5]||(e[5]=d("p",null,"disabled 落成原生 fieldset[disabled]，组内每个控件一并停掉，不必逐个写 disabled",-1)),o(a,{src:"fieldset/02-disabled"}),e[6]||(e[6]=d("h3",{id:"无效态",tabindex:"-1"},[t("无效态 "),d("a",{class:"header-anchor",href:"#无效态","aria-label":'Permalink to "无效态"'},"​")],-1)),e[7]||(e[7]=d("p",null,"invalid 一翻，错误文案接进描述链并显出；它带 role=alert，翻转那一刻读屏立即播报",-1)),o(a,{src:"fieldset/03-invalid"}),e[8]||(e[8]=d("h3",{id:"必填标记",tabindex:"-1"},[t("必填标记 "),d("a",{class:"header-anchor",href:"#必填标记","aria-label":'Permalink to "必填标记"'},"​")],-1)),e[9]||(e[9]=d("p",null,"required 落成 data-required，皮肤据此给组标题加星号；星号只是视觉冗余，必填这件事要一并写进文案",-1)),o(a,{src:"fieldset/04-required"}),e[10]||(e[10]=d("h3",{id:"总开关放进-legend",tabindex:"-1"},[t("总开关放进 legend "),d("a",{class:"header-anchor",href:"#总开关放进-legend","aria-label":'Permalink to "总开关放进 legend"'},"​")],-1)),e[11]||(e[11]=d("p",null,"按 HTML 规范，首个 legend 里的控件不受 fieldset[disabled] 连坐，总开关因此始终可点",-1)),o(a,{src:"fieldset/05-legend-switch"}),e[12]||(e[12]=r('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-fieldset&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhFieldsetErrorText</code> <code>XhFieldsetHelperText</code> <code>XhFieldsetLegend</code> <code>XhFieldsetRoot</code></td></tr><tr><td>组合式函数</td><td><code>useFieldset</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/fieldset.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;fieldset&quot;</code>：<strong><code>root</code></strong> · <strong><code>legend</code></strong> · <code>helper-text</code> · <code>error-text</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>整组禁用。root 是原生 <code>&amp;lt;fieldset&amp;gt;</code>，这一条落成原生 disabled 属性， 浏览器会把组内每个表单控件一并停掉（首个 <code>&amp;lt;legend&amp;gt;</code> 里的控件按 HTML 规范除外）。</td></tr><tr><td><code>invalid</code></td><td><code>boolean</code></td><td></td><td>校验失败态：root 上落 data-invalid，错误文案接入描述链并显出。</td></tr><tr><td><code>required</code></td><td><code>boolean</code></td><td></td><td>必填标记：落成 data-required，供皮肤给组标题加星号，校验仍归宿主。 不产出 aria-required —— 该属性在 group 角色上不被支持，写了也不进无障碍树。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;FieldsetTranslations&gt;</code></td><td></td><td>文案覆盖。本组件当前没有外露文案，位先留着，接全局配置的通道由适配器铺好。</td></tr></tbody></table><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useFieldset</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>invalid</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>required</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLegendProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getHelperTextProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getErrorTextProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://html.spec.whatwg.org/multipage/form-elements.html#the-fieldset-element" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-describedby</code></td><td><code>helper-text</code> 部件的 id <code>error-text</code> 部件的 id | <code>helper-text</code> 部件的 id</td></tr><tr><td><code>error-text</code></td><td><code>role</code></td><td>&#39;alert&#39;</td></tr></tbody></table><ul><li>组名来自原生 <code>&lt;legend&gt;</code>，它必须是 <code>&lt;fieldset&gt;</code> 的首个子节点，否则浏览器不把它当组名。</li><li>组标题不再另发 <code>aria-labelledby</code>：多一份名字来源会与原生那份叠加，读屏把组名念两遍。</li><li>根节点不产出 <code>aria-invalid</code> / <code>aria-required</code>——这两个属性在 <code>group</code> 角色上不被支持，写了也不进无障碍树；无效与必填的读屏出口是错误文案与描述链。</li><li><strong>只要 <code>invalid</code> 有可能为真，就必须渲染错误文案部件。</strong> 它是这一态唯一的读屏出口：组标题转色只是视觉提示，无障碍树里一个字节都不会变。</li><li><strong>必填要写进组标题的可见文字或说明文案</strong>（&quot;通知方式（必填）&quot;、&quot;以下三项至少填一项&quot;）。皮肤的星号是 CSS 生成内容，用户自定义样式表关掉 <code>content</code> 或读屏不朗读生成内容时它就不存在了，只能当视觉冗余。</li><li>按 HTML 规范，首个 <code>&lt;legend&gt;</code> 里的控件不受 <code>fieldset[disabled]</code> 连坐。想让一个开关在整组停用时仍可操作（例如&quot;启用本段&quot;的总开关），就把它放进 <code>&lt;legend&gt;</code>。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/fieldset.css</code> 按部件选择：<code>[data-scope=&quot;fieldset&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-required</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>legend</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>helper-text</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-fieldset-error-fg</code> · <code>--xh-fieldset-error-font-size</code> · <code>--xh-fieldset-gap</code> · <code>--xh-fieldset-helper-fg</code> · <code>--xh-fieldset-helper-fg-disabled</code> · <code>--xh-fieldset-helper-font-size</code> · <code>--xh-fieldset-legend-fg</code> · <code>--xh-fieldset-legend-fg-disabled</code> · <code>--xh-fieldset-legend-fg-invalid</code> · <code>--xh-fieldset-legend-font-size</code> · <code>--xh-fieldset-legend-font-weight</code> · <code>--xh-fieldset-legend-gap</code> · <code>--xh-fieldset-legend-star</code></p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>里面按顺序放若干<a href="./field">表单字段</a>，每格自己管标签与错误文案。</li><li>一组单选放<a href="./radio-group">单选组</a>、一组多选放<a href="./checkbox-group">复选框组</a>。<strong>这两个组仍要写自己的 <code>label</code> 部件</strong>：字段集的标题命名的是外层这一段，内层那一组要自己有名字，legend 不会往下传。</li><li>外面套<a href="./form">表单</a>统一收值与校验，字段集只承担分组与整段禁用。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>组标题写成一句能读通的名词短语或问句（&quot;通知方式&quot;而不是&quot;选项&quot;）——读屏进组时念的就是它。</li><li>整段停用优先写在字段集上，别逐个控件写 <code>disabled</code>：漏一个就是一个能点却不该点的控件。</li><li>错误文案说清楚整组哪里不满足（&quot;至少填写一种联系方式&quot;），单格自己的错误留给该格的字段。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>用 <code>&lt;div&gt;</code> 冒充字段集：禁用不再连坐，读屏也听不出这是一组。</li><li>把 <code>&lt;legend&gt;</code> 挪到中间或包一层容器：它一旦不是首个子节点，就不再是这一组的名字。</li><li>只用一条分割线和一行加粗文字表示分组：视觉上像一组，无障碍树里仍是散的。</li><li>一个字段集里塞进三四个互不相关的主题，标题只好写成&quot;其他&quot;。</li><li>打开 <code>invalid</code> 却不渲染错误文案：屏幕上只有组标题换了个颜色，读屏用户完全不知道这一组出了问题。</li></ul>',33))])}const k=c(h,[["render",u]]);export{P as __pageData,k as default};
